/* eslint-disable react/prop-types */
// src/components/App.js

import React from 'react';
import TonalitySelector from './TonalitySelector';
import SettingsPanel from './SettingsPanel'; // Импорт нашего нового компонента
import OutputDisplay from './OutputDisplay';
import useChordGenerator from '../hooks/useChordGenerator';
import { keyPairs, keySignatures } from '../data/vocabulary'; 

function App() {
  const { state, sequence, handleInput } = useChordGenerator();

  if (state === undefined || sequence === undefined) {
    return null;
  }

  // --- НОВАЯ ЛОГИКА РЕНДЕРИНГА ---
  if (state === 'chooseKeyNum') {
    // Состояние по умолчанию: показываем таблицу для выбора тональности
    return (
      <div className="min-h-screen bg-gray-900 text-white p-8">
        {/* Начальный контент */}
        <TonalitySelector
          onSelect={handleInput}
          keyPairs={keyPairs}       // <-- ДОБАВЬТЕ ЭТУ СТРОКУ
          keySignatures={keySignatures} // <-- И ЭТУ ТОЖЕ
        />
      </div>
    );
  } else if (state === 'chooseChords') {
    // Новое состояние: пользователь выбрал тональность, теперь выбираем аккорды
    // Предполагаем, что хук вернул нам список аккордов в ключе "key"
    // Для этого хук должен возвращать "selectedChords" или мы должны его получить через контекст.
    // Но проще всего передать key в этот компонент.
    
    // Давайте предположим, что хук возвращает selectedChords.
    // Если нет, вам нужно обновить хук, чтобы он их возвращал.
    const { key, selectedChords } = useChordGenerator(); // <-- Возможно, потребуется рефакторинг хука

    return (
      <div className="min-h-screen bg-gray-900 text-white p-8 space-y-8">
        <h2 className="text-xl font-semibold mb-4">🎹 Шаг 2. Выберите аккорды для генерации.</h2>
        <p className="mb-6 text-lg">
          Выбрана тональность: <span className="font-bold">{key}</span><br />
          Её аккорды ниже.
        </p>

        {/* Блок с чекбоксами */}
        <form id="chord-selection-form">
          <div id="chord-checkboxes">
            {selectedChords.map((chord, index) => (
              <label key={index} className="chord-checkbox">
                <input type="checkbox" name="chord" value={index + 1} defaultChecked /> {index + 1}. {chord}
              </label>
            ))}
          </div>
          <div className="flex flex-col sm:flex-row gap-3 mt-6 w-full justify-center">
            <button type="submit" className="ready-btn">Готово</button>
            <button type="button" className="select-all-btn">Выбрать все</button>
            <button type="button" className="deselect-all-btn">Снять выделение</button>
          </div>
        </form>
        <p className="mt-8 text-sm text-gray-400">
          ⚠️ Для применения кадансов необходимо выбрать аккорды, соответствующие ступеням тональности 1, 4-7.
        </p>
      </div>
    );
  } else {
    // Все остальные состояния (например, когда sequence уже есть)
    return (
      <div className="min-h-screen bg-gray-900 text-white p-8">
        <div className="grid md:grid-cols-2 gap-8">
          <SettingsPanel onChange={handleInput} />
          <OutputDisplay sequence={sequence} />
        </div>
      </div>
    );
  }
}

export default App;
